import {openVault} from './vault.js';
import {localService,trainingState} from './local-service.js';
const vault=await openVault(),service=localService(vault),localStorage=vault.storage;
import {completedActivities} from './activity-log.js';
import {lessonView,archiveView,repLabel} from './workout-plan-ui.js';
import {refreshSwipe} from './refresh-control.js';
import {catalogExercise,customExercise,videoEmbedUrl,videoWatchUrl} from './exercise-catalog.js';
import {highlights} from './highlights-ui.js';
import {fullCalendarDate} from './calendar-ui.js';
let statsView='training';

import {exerciseProgression,removeWorkoutSet} from './progression.js';
import {muscleBadge,exerciseGuide,finishForm,cardioFinisher,muscleStrip} from './exercise-ui.js';
const local={cache(){}};
let progressContext=null,removedSet=null,flushPromise=null,surveyWorkoutId=null,offlineMode=false;
import {exerciseHistory,exerciseKey,plateauInsight,weekSummary,programSequence} from './progress-insights.js';
import {exercises,swimVideos,findExercise,replacements,variants,makeThreeDayPlan,gear,upcomingSessions,assessPlan,sessionAdvice} from './training-library.js';
const $=s=>document.querySelector(s),root=$('#app'),modal=$('#modal');
const paths={watch:'M9 2h6l1 4M9 2 8 6M8 18l1 4h6l1-4M7 6h10a2 2 0 0 1 2 2v8a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2M12 9v3l2 1',walk:'M14 5a2 2 0 1 0 .1 0M8 22l3-7-3-4 3-4 4 5h5M5 12l3-1M15 16l4 5',bike:'M9 17a4 4 0 1 1-8 0a4 4 0 0 1 8 0M23 17a4 4 0 1 1-8 0a4 4 0 0 1 8 0M5 17l5-10 5 10H5M10 7h5l4 10M8 4h4M15 4h3',food:'M4 3v7q0 3 3 3V3M4 7h3M5.5 13v8M17 3c-4 4-4 9 0 9h2V3M19 12v9',leaf:'M20 3C9 1 2 8 5 15s14 3 15-12M4 21 15 10',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8',home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z',gym:'M6 5v14M3 8v8M18 5v14M21 8v8M6 12h12',swim:'M2 20q3-3 6 0t6 0t6 0M4 15l5-5 4 3 4-2M9 10l4-5 4 2M18 5a2 2 0 1 0 .1 0',run:'M14 5a2 2 0 1 0 .1 0M8 22l3-7-3-4 3-4 4 5h5M5 12l3-1M15 16l4 5',stats:'M4 20V10M10 20V4M16 20v-7M22 20V8',user:'M20 21v-2a7 7 0 0 0-14 0v2M13 11a4 4 0 1 0-.1 0',arrow:'M5 12h14m-6-6 6 6-6 6',chevron:'m9 5 7 7-7 7',plus:'M12 5v14M5 12h14',close:'m6 6 12 12M6 18 18 6',check:'m5 12 4 4L19 6',clock:'M12 8v5l3 2M22 12a10 10 0 1 0-20 0 10 10 0 0 0 20 0',weight:'M5 8h14l3 13H2zM8 8V6a4 4 0 0 1 8 0v2',steps:'M8 14c-5 2-6 5-3 7s6 0 6-3-1-5-3-4M16 10c5-2 6-5 3-7s-6 0-6 3 1 5 3 4',fire:'M12 2c1 6 7 8 7 13a7 7 0 0 1-14 0c0-4 3-6 4-8 0 5 3 5 3 5z',moon:'M21 13A9 9 0 0 1 11 3a9 9 0 1 0 10 10',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',upload:'M12 16V4m-5 5 5-5 5 5M4 16v5h16v-5',bell:'M5 17h14l-2-4V9a5 5 0 0 0-10 0v4zM10 21h4',link:'m9 15 6-6M8 17l-2 2a4 4 0 0 1-5-5l5-5a4 4 0 0 1 6 0M16 7l2-2a4 4 0 0 1 5 5l-5 5a4 4 0 0 1-6 0',edit:'m16 3 5 5-12 12-6 1 1-6z',refresh:'M20 8a9 9 0 1 0 1 8M20 3v5h-5',pause:'M8 5v14M16 5v14',play:'m7 3 14 9-14 9z',chat:'M21 15a3 3 0 0 1-3 3H8l-5 4V5a3 3 0 0 1 3-3h12a3 3 0 0 1 3 3z'};
const icon=(name,cls='')=>`<svg class="ico ${cls} ${['gym','swim','run','walk','bike'].includes(name)?'sport-'+name:''}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.gym}"/></svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const types={gym:'Зал',swim:'Плавание',home:'Дома',run:'Бег',walk:'Ходьба',bike:'Велосипед',other:'Активность'};
const days=['Вс','Пн','Вт','Ср','Чт','Пт','Сб'];
let data=null,tab='today',authMode='login',period=30,active=null,editSession=null,saveTimer,restUntil=0,noticeTimer,lastRenderedTab=null,selectedDay=null,calendarWeek=0,calendarMonth=null,preparingId=null,selectedSessionId=null,sessionReturn=null;
const dateDay=(d=new Date())=>{const p=new Intl.DateTimeFormat('en-CA',{year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(d);const o=Object.fromEntries(p.map(x=>[x.type,x.value]));return `${o.year}-${o.month}-${o.day}`;};
selectedDay=dateDay();
const fmt=(n,d=0)=>Number(n).toLocaleString('ru-RU',{maximumFractionDigits:d});
const humanDate=d=>new Date(d).toLocaleDateString('ru-RU',{day:'numeric',month:'short'});
const time=n=>`${Math.floor(n/60).toString().padStart(2,'0')}:${Math.floor(n%60).toString().padStart(2,'0')}`;
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4000);}
async function api(path,b){try{return await service.call(path,b);}catch(e){if(!e.status)e.status=503;throw e;}}
async function refresh(){data=await api('state');offlineMode=false;const unfinished=data.workouts.find(w=>!w.completedAt);if(unfinished&&!active){active=unfinished;tab='workout';}render();}
function upsertLocalWorkout(w){data.workouts=[w,...data.workouts.filter(x=>x.id!==w.id)].sort((a,b)=>b.startedAt.localeCompare(a.startedAt));}
async function flushPending(){await vault.drain();}
function openModal(title,html){$('#modal-content').innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2><button class="icon-button" data-action="close" aria-label="Закрыть">${icon('close')}</button></div>${html}`;if(!modal.open)modal.showModal();animateSheet();}
const button=(action,label,cls='secondary',extra='')=>`<button type="button" class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
function field(name,label,value='',type='text',attrs=''){return `<div class="field"><label for="${name}">${esc(label)}</label><input id="${name}" name="${name}" type="${type}" value="${esc(value)}" ${attrs}></div>`;}
function renderAuth(){const existing=vault.exists();root.innerHTML=`<main class="auth"><div class="wordmark">fitassist.</div><p class="eyebrow mb16">Только твои тренировки</p><h1>Твой план.<br>На твоём устройстве.</h1><p class="muted">Программа, подходы и прогресс сохраняются здесь.</p><form id="auth-form">${field('password',existing?'Пароль':'Придумай пароль','','password','required minlength="10" maxlength="200" autocomplete="'+(existing?'current-password':'new-password')+'"')}${existing?'':field('confirmPassword','Повтори пароль','','password','required minlength="10" maxlength="200" autocomplete="new-password"')}<p class="caption">${existing?'Введи пароль для расшифровки своих записей.':'От 10 символов. Сохрани пароль: восстановить его через почту нельзя.'}</p><div id="auth-error" role="alert"></div><button type="submit" class="primary full spaced">${existing?'Открыть мои тренировки':'Создать своё хранилище'}</button></form><p class="auth-footer">Личная база зашифрована. На новом устройстве понадобится резервная копия.</p></main>`;}
function nav(mobile=false){return `<nav class="${mobile?'mobile-nav':'nav'}" aria-label="Основная навигация">${[['today','home','Главная'],['training','gym','Тренировки'],['stats','stats','Прогресс']].map(([id,i,name])=>button('tab',`${icon(i)}<span>${name}</span>`,tab===id?'active':'',`data-tab="${id}" aria-current="${tab===id?'page':'false'}"`)).join('')}</nav>`;}
const completed=()=>completedActivities(data);
function weeklyWorkouts(){const d=new Date((selectedDay||dateDay())+'T12:00:00');d.setHours(0,0,0,0);d.setDate(d.getDate()-((d.getDay()+6)%7));return completed().filter(w=>new Date(w.startedAt||w.completedAt)>=d&&new Date(w.startedAt||w.completedAt)<new Date(d.getTime()+7*86400000));}
function render(){if(!data)return renderAuth();document.documentElement.dataset.section=['prepare','session','workout'].includes(tab)?'training':tab;const key=tab==='stats'?tab+':'+statsView:tab,changed=lastRenderedTab!==key;lastRenderedTab=key;root.innerHTML=`<div class="shell ${['workout','prepare','session'].includes(tab)?'workout-mode':''}"><aside class="sidebar"><div class="wordmark">fitassist.</div>${nav()}<div class="foot">Тренировки на этом устройстве</div></aside><main class="content ${changed?'page-enter':''}">${active&&tab!=='workout'?'<div class="info row between mb16"><span>Тренировка ещё идёт</span>'+button('resume','Продолжить','secondary')+'</div>':''}${tab==='today'?renderToday():tab==='training'?renderTraining():tab==='stats'?renderStats():tab==='workout'?renderWorkout():tab==='prepare'?renderPreparation():tab==='session'?renderSessionDetails():renderProfile()}</main>${['workout','prepare','session'].includes(tab)?'':nav(true)}</div>`;tick();if(changed)animatePage();}
function refreshControl(compact=false){return button('refresh-data',icon('refresh')+(compact?'':'<span>Обновить</span>'),'ghost data-refresh '+(compact?'icon-button home-refresh':'refresh-label-button'),`aria-label="Обновить данные" title="Обновить данные" ${manualRefresh||active?'disabled':''}`);}
function header(title,subtitle,action=null){return `<header class="topbar"><h1>${esc(title)}</h1>${action?button(action,icon('plus'),'icon-button','aria-label="Добавить тренировку"'):['Прогресс','Тренировки'].includes(title)?refreshControl(true):''}</header>`;}
function renderToday(){
 const all=completed(),day=new Date(selectedDay+'T12:00:00'),monday=new Date(day);monday.setDate(day.getDate()-((day.getDay()+6)%7));
 const selectedIndex=(day.getDay()+6)%7;
 const calendar=Array.from({length:7},(_,i)=>{const x=new Date(monday);x.setDate(x.getDate()+i);const key=dateDay(x),records=all.filter(w=>dateDay(new Date(w.startedAt||w.completedAt))===key),kinds=[...new Set(records.map(w=>w.type))];return '<button class="day '+(key===selectedDay?'is-selected':'')+' '+(records.length?'done':'')+'" data-action="calendar-day" data-day="'+key+'" aria-label="'+x.toLocaleDateString('ru-RU',{day:'numeric',month:'long'})+(records.length?', выполнено занятий: '+records.length+' ('+kinds.map(t=>types[t]).join(', ')+')':'')+'" aria-current="'+(key===dateDay()?'date':'false')+'" aria-pressed="'+(key===selectedDay)+'"><span class="weekday">'+days[x.getDay()]+'</span><span class="num">'+x.getDate()+'</span><span class="day-marks">'+kinds.slice(0,3).map(t=>'<span class="activity-dot dot-'+t+'"></span>').join('')+'</span></button>';}).join('');
 const next=programSequence(data.plan.sessions,data.workouts)[0];
 return `<header class="home-header calendar-home-header"><h1 class="sr-only">Главная</h1>${button('calendar-open','<span>'+day.toLocaleDateString('ru-RU',{month:'long'})+'</span><small>'+day.getFullYear()+'</small>'+icon('chevron'),'calendar-month-button','aria-label="Открыть полный календарь"')}<div class="calendar-controls">${button('calendar-prev',icon('chevron'),'icon-button calendar-prev','aria-label="Предыдущая неделя"')}${button('calendar-today',icon('refresh'),'calendar-return',`aria-label="К текущей дате" ${selectedDay===dateDay()?'disabled':''}`)}${button('calendar-next',icon('chevron'),'icon-button','aria-label="Следующая неделя"')}</div>${refreshControl(true)}${button('profile','<img src="./avatar.svg" alt="" width="44" height="44">','profile-orb','aria-label="Открыть профиль"')}</header><section class="calendar-panel" aria-label="Календарь тренировок"><div class="week" data-week="${dateDay(monday)}"><span class="week-selection" data-index="${selectedIndex}" aria-hidden="true"></span>${calendar}</div><p class="selected-date sr-only" aria-live="polite">${esc(fullCalendarDate(selectedDay))}</p></section>${highlights(data,icon,{compact:true})}<article class="card hero training-hero spaced"><div class="row between"><span class="eyebrow">${next?'Следующая тренировка':'Твоя программа'}</span>${next?`<span class="badge">${sessionLabel(next)}</span>`:''}</div>${next?'<div class="home-muscles"><span class="history-icon">'+icon(next.type)+'</span>'+muscleStrip(next)+'</div>':''}<h2 class="mt12">${next?esc(next.name):'Выбери удобный ритм'}</h2><p class="caption mt12">${next?`${next.duration} мин · ${next.exercises.length?next.exercises.length+' упражнений':'плавание с отдыхом'}`:'Готовый вариант или своя программа.'}</p><div class="stack spaced">${next?button('start','Начать','primary full',`data-id="${esc(next.id)}"`):button('program-wizard','Выбрать программу','primary full')}</div></article>`;
}

function history(rows,emptyTitle='История начинается здесь'){if(!rows.length)return `<div class="empty"><h3>${esc(emptyTitle)}</h3><p>${emptyTitle==='История начинается здесь'?'Завершённые тренировки появятся в этом разделе.':'Выбери другой день или посмотри всю историю.'}</p></div>`;return rows.map(w=>`<button class="history-row full" data-action="workout-details" data-id="${esc(w.id)}"><span class="history-icon">${icon(w.type)}</span><div class="history-main"><h3>${esc(w.name)}</h3><p class="history-meta">${humanDate(w.completedAt)} · ${types[w.type]}${w.external?' · С часов':''}${w.feedback?' · '+{easy:'Легко',good:'В самый раз',hard:'Тяжело'}[w.feedback]:''}</p></div><div class="text-right"><strong>${w.elapsed<60?'&lt;1':Math.round(w.elapsed/60)} <span class="unit">мин</span></strong><p class="history-meta">${w.distance?fmt(w.distance)+' м':w.external?'С часов':w.exercises.reduce((sum,e)=>sum+e.sets.filter(s=>s.done).length,0)+' подх.'}</p></div></button>`).join('');}
function renderTraining(){return `${header('Тренировки','')}<p class="muted">${esc(data.plan.title)}</p><div class="plan-grid spaced">${data.plan.sessions.map((s,i)=>`<article class="card plan-card"><div class="row between plan-card-top"><div class="plan-symbols"><span class="history-icon">${icon(s.type)}</span>${muscleStrip(s)}</div><span class="tag">День ${i+1}</span></div><div><h2>${esc(s.name)}</h2><p class="caption mt8">${s.duration} мин · ${s.exercises.length?s.exercises.length+' упражнений':'время и дистанция'}</p></div><div class="actions">${button('start','Начать','primary',`data-id="${esc(s.id)}"`)}${button('session-details','План','secondary',`data-id="${esc(s.id)}" aria-label="План: ${esc(s.name)}"`)}</div></article>`).join('')}</div>${!data.plan.sessions.length?'<div class="card spaced"><h2>Твой первый план</h2><p class="caption mt12">Выбери готовый вариант или собери свою неделю из каталога упражнений.</p></div>':''}<div class="training-bottom-actions spaced">${button('program-wizard','Готовые варианты','primary')}${button('custom-program','Изменить свою','secondary')}</div><div class="program-tools spaced">${button('new-custom-program','Собрать с нуля','ghost small')}</div>`;}
function renderStats(){
 const cutoff=dateDay(new Date(Date.now()-period*86400000)),rows=completed().filter(w=>dateDay(new Date(w.startedAt||w.completedAt))>=cutoff),minutes=Math.round(rows.reduce((n,w)=>n+w.elapsed,0)/60),sets=rows.reduce((n,w)=>n+w.exercises.reduce((m,e)=>m+e.sets.filter(s=>s.done).length,0),0),distance=rows.filter(w=>w.type==='swim').reduce((n,w)=>n+w.distance,0);
 const groups=new Map();for(const w of rows)for(const e of w.exercises){const done=e.sets.filter(s=>s.done);if(!done.length)continue;const last=groups.get(exerciseKey(e));if(!last||last.date<w.completedAt)groups.set(exerciseKey(e),{identity:e,name:e.name,date:w.completedAt,weight:Math.max(...done.map(s=>s.weight)),sets:done.length});}
 return `${header('Прогресс','')}${weeklySummaryView()}<div class="section-head"><h2>За выбранный период</h2></div><div class="tabs" aria-label="Период статистики">${[7,30,90].map(n=>button('period',`${n} дней`,n===period?'active':'',`data-period="${n}"`)).join('')}</div><div class="workout-stat-grid">${[[rows.length,'занятий','gym'],[minutes,'минут','clock'],[sets,'подходов','check'],[fmt(distance),'м в бассейне','swim']].map(([n,l,i])=>`<article class="card workout-stat"><span class="stat-symbol stat-${i}">${icon(i)}</span><p class="number">${n}</p><p class="caption mt8">${l}</p></article>`).join('')}</div><div class="section-head"><h2>История упражнений</h2></div><div class="card quiet">${groups.size?[...groups].map(([name,v])=>`<button class="load-row full exercise-history-link" data-action="exercise-history" ${historyIdentity(v.identity)}><span><strong>${esc(v.name)}</strong><span class="caption mt8">${humanDate(v.date)} · ${v.sets} подх. · история и график</span></span><span class="load-number">${v.weight?fmt(v.weight)+' кг':'Без веса'}${icon('chevron')}</span></button>`).join(''):'<div class="empty"><h3>Здесь появятся твои результаты</h3><p>Во время тренировки записывай вес и отмечай выполненные подходы.</p></div>'}</div>${plateauOverview()}<div class="section-head"><h2>История за период</h2></div><div class="card quiet">${history(rows)}</div>`;
}
function progressDetailHeader(title){return '<div class="page-header">'+button('progress-overview',icon('chevron')+'Весь прогресс','ghost detail-back')+header(title,'')+'</div>';}
function renderPreparation(){
 const s=data.plan.sessions.find(s=>s.id===preparingId);if(!s){preparingId=null;tab='training';return renderTraining();}
 const checklist=gearChecklist(s.type,dateDay()).replace('<details class="card gear-card spaced">','<details class="card gear-card spaced" open>');
 return '<div class="preparation-container">'+'<header class="preparation-nav">'+button('prepare-back',icon('chevron')+'К тренировкам','ghost detail-back')+'<span class="caption">Подготовка</span></header>'+'<div class="preparation-heading"><span class="history-icon">'+icon(s.type)+'</span><p class="eyebrow">До старта · подготовка</p><h1>'+esc(s.name)+'</h1><p class="caption mt12">'+s.duration+' мин · '+(s.exercises.length?s.exercises.length+' упражнений':'план плавания')+'</p></div>'+checklist+'<section class="card preparation-warmup spaced"><span class="stat-symbol stat-clock">'+icon('clock')+'</span><h2>Подготовься в своём темпе</h2><p class="caption mt12">'+(s.type==='swim'?'Переоденься, прими душ и посмотри план. Нажми «Старт» перед входом в воду. Все результаты запишешь после бассейна.':'Разомнись и посмотри порядок упражнений. Разминку записывать не нужно. Время занятия начнёт считаться только после «Старт».')+'</p></section><div class="section-head"><h2>Что будем делать</h2></div><div class="card preparation-plan">'+(s.exercises.length?s.exercises.map((e,i)=>'<article class="prep-exercise"><div class="row"><span class="exercise-order">'+(i+1)+'</span><div><h3>'+esc(e.name)+'</h3><p class="caption mt8">'+e.sets+' подхода · '+repLabel(e)+' повторов</p></div></div>'+exerciseBrief(e)+techniqueButton(e)+'</article>').join(''):lessonView(s.note||'Спокойные отрезки по 25 метров с отдыхом между ними.',s.type)+swimTechniqueLinks())+'</div>'+(s.exercises.length&&s.note?'<details class="card spaced"><summary>План и нагрузка</summary><p class="caption plan-note mt12">'+esc(s.note)+'</p></details>':'')+'<div class="preparation-start"><p class="caption">Готов? Начинаем отсчёт.</p>'+button('begin-workout','Старт '+icon('play'),'primary full')+'</div></div>';
}
function renderProfile(){return '<div class="page-header">'+button('home',icon('chevron')+'Главная','ghost detail-back')+header('Профиль','')+'</div><form id="profile-form" class="card profile-editor"><div class="profile-identity"><img src="./avatar.svg" alt="Нейтральный аватар" width="88" height="88"><div><p class="eyebrow">Твои тренировки</p><p class="caption">Сохранены на этом устройстве</p></div></div>'+field('name','Как тебя называть?',data.profile.name||'','text','maxlength="60" autocomplete="given-name"')+'<fieldset class="weekly-goal-picker"><legend>Занятий в неделю</legend><div class="goal-options">'+[1,2,3,4,5,6,7].map(n=>'<label><input type="radio" name="weeklyGoal" value="'+n+'" '+(data.profile.weeklyGoal===n?'checked':'')+'><span>'+n+'</span></label>').join('')+'</div></fieldset><div class="profile-save-row"><span id="profile-save-status" class="caption">Всё сохранено</span><button type="submit" class="primary" disabled>Сохранить</button></div></form><div class="section-head"><h2>Твои данные</h2></div><div class="card">'+profileLink('backup','Сохранить копию','Зашифрованный файл с программой и историей','download')+profileLink('restore','Восстановить или перенести','Копия или сводка из прежнего FitAssist','upload')+profileLink('export','Сводка для чата','Открытый JSON только о тренировках','chat')+profileLink('import','Загрузить программу','Файл JSON программы','gym')+profileLink('logout','Заблокировать','Для открытия понадобится пароль','user')+'</div><p class="caption spaced">Сохраняй копию после важных занятий. Данные на разных устройствах сами не синхронизируются.</p>';}
function profileLink(action,title,desc,i){return `<button class="profile-link" data-action="${action}"><span class="row">${icon(i)}<span>${esc(title)}<span class="caption">${esc(desc)}</span></span></span>${icon('chevron')}</button>`;}
function renderWorkout(){if(!active){tab='training';return renderTraining();}return `<div class="workout-container"><header class="workout-header"><div class="workout-header-top">${button('workout-options',icon('chevron')+'Назад','ghost workout-back','aria-label="Выйти из экрана тренировки"')}<div class="row"><time id="elapsed" class="workout-clock">${time(elapsed())}</time>${button('workout-options',icon('close'),'icon-button','aria-label="Меню тренировки"')}</div></div><h1 class="workout-title">${esc(active.name)}</h1><p class="save-state" id="save-state">Изменения сохраняются автоматически</p></header>${active.type==='swim'?swimTechniqueLinks():''}${active.type==='swim'?'<div class="info spaced">Следуй плану ниже и отдыхай между отрезками. После бассейна нажми «Завершить»: запишешь общую дистанцию, длительность.</div>':active.type==='run'?`<div class="card spaced">${field('workout-distance','Дистанция, м',active.distance||'','number','min="0" max="1000000"')}</div>`:''}${active.note?`<details class="session-guidance card spaced" ${active.type==='swim'?'open':''}><summary><span class="guidance-copy"><strong>${active.type==='swim'?'План плавания':'План занятия'}</strong><small>Порядок, нагрузка и отдых</small></span>${icon('chevron')}</summary>${lessonView(active.note,active.type)}</details>`:''}<div class="card spaced">${active.exercises.length?active.exercises.map((e,ei)=>`${exerciseIsFolded(ei)?`<section class="exercise exercise-folded"><button class="exercise-fold-toggle" data-action="exercise-expand" data-ex="${ei}" aria-label="Раскрыть ${esc(e.name)}"><span class="exercise-fold-check">${icon('check')}</span><span><strong>${esc(e.name)}</strong><small>${e.sets.filter(s=>s.done).length} подхода выполнено · ${e.sets.filter(s=>s.done).map(s=>fmt(s.weight)+' кг × '+s.reps).join(' · ')}</small></span>${icon('chevron')}</button></section>`:`<section class="exercise" data-exercise-index="${ei}"><div class="row between"><h2>${esc(e.name)}</h2><span class="set-count" aria-label="Выполнено ${e.sets.filter(s=>s.done).length} из ${e.sets.length} подходов">${e.sets.filter(s=>s.done).length} из ${e.sets.length}</span></div>${exerciseBrief(e)}<p class="caption mt8">Цель: ${repLabel(e)} повторов · отдых ${e.rest} сек</p>${muscleBadge(e)}${previousExerciseView(e)}${archiveView(data.profile?.trainingArchive,e)}${techniqueButton(e)}<div class="set-head with-delete"><span>№</span><span>${active.type==='swim'?'Метры':'Кг'}</span><span>${active.type==='swim'?'Отрезки':'Повторы'}</span><span>Готово</span><span></span></div>${e.sets.map((s,si)=>`<div class="set-row with-delete ${s.done?'complete':''}"><span class="set-index">${si+1}</span><input type="number" min="0" max="1000" step="0.25" value="${s.weight}" data-ex="${ei}" data-set="${si}" data-key="weight" aria-label="${esc(e.name)}, подход ${si+1}, ${active.type==='swim'?'дистанция':'вес'}"><input type="number" min="0" max="10000" value="${s.reps}" data-ex="${ei}" data-set="${si}" data-key="reps" aria-label="${esc(e.name)}, подход ${si+1}, повторения"><button class="set-check" data-action="set-done" data-ex="${ei}" data-set="${si}" aria-label="${s.done?'Отменить':'Отметить'} подход ${si+1}">${icon('check')}</button>${button('remove-set','×','delete-set',`data-ex="${ei}" data-set="${si}" aria-label="Удалить подход ${si+1}" ${e.sets.length===1?'disabled':''}`)}</div>`).join('')}<div class="exercise-complete-actions">${button('add-set','+ Подход','ghost small',`data-ex="${ei}"`)}${button('exercise-collapse',icon('check')+' Упражнение закончено','secondary exercise-finish',`data-ex="${ei}" ${e.sets.every(s=>s.done)?'':'disabled'} `)}</div></section>`}`).join(''):'<p class="caption">После выхода запиши общий результат. Во время плавания отмечать отрезки не нужно.</p>'}</div>${cardioFinisher(active)}<div class="stack spaced">${button('finish','Завершить тренировку','primary full')}${button('discard','Отменить занятие','ghost danger')}</div></div>`;}
function elapsed(){return active?Math.max(0,Math.floor((Date.now()-new Date(active.startedAt).getTime())/1000)):0;}
function tick(){if($('#elapsed'))$('#elapsed').textContent=time(elapsed());const el=$('#rest-timer');if(el){const left=Math.ceil((restUntil-Date.now())/1000);el.innerHTML=left>0?`<div class="timer"><span>Отдых <strong>${time(left)}</strong></span>${button('skip-rest','Пропустить','')}</div>`:'';}}
setInterval(tick,1000);
let saveChain=Promise.resolve();
function saveWorkout(){if(!active)return Promise.resolve();const snapshot=structuredClone({...active,elapsed:active.manualElapsed??elapsed()});saveChain=saveChain.catch(()=>{}).then(async()=>{const el=$('#save-state');if(el)el.textContent='Сохраняем…';try{await api('workout',{workout:snapshot});upsertLocalWorkout(snapshot);await localStorage.removeItem('fitassist-draft-'+data.user.id);if(el)el.textContent='Сохранено на устройстве';}catch(e){if(el)el.textContent='Не удалось сохранить';throw e;}});return saveChain;}
function queueSave(){clearTimeout(saveTimer);localStorage.setItem('fitassist-draft-'+data.user.id,JSON.stringify({...active,elapsed:elapsed()}));saveTimer=setTimeout(()=>saveWorkout().catch(()=>{}),600);}
function exportData(){download('fitassist-training-report.json',JSON.stringify({format:'fitassist-training-report-v1',exportedAt:new Date().toISOString(),...trainingState(data)},null,2));toast('Сводка тренировок скачана');}
function download(name,text){const a=document.createElement('a');const url=URL.createObjectURL(new Blob([text],{type:'application/json;charset=utf-8'}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function editor(session){editSession=structuredClone(session||{id:crypto.randomUUID(),name:'',type:'gym',day:null,duration:45,note:'',exercises:[]});renderEditor();}
function editorExercise(e,i){const c=findExercise(e);return `<article class="editor-exercise"><div class="row between"><span class="tag">${c?'Из каталога':'Своё упражнение'}</span>${button('remove-exercise',icon('close'),'icon-button',`data-index="${i}" aria-label="Удалить упражнение"`)}</div>${c?`<div class="editor-identity"><h3>${esc(c.name)}</h3><p class="caption mt8">${esc(c.equipment)}</p></div><input type="hidden" id="e-name-${i}" value="${esc(c.name)}">`:field('e-name-'+i,'Название упражнения',e.name,'text','required maxlength="160" placeholder="Как называется движение?"')}<div class="exercise-actions mt12">${button('editor-replace',c?'Заменить упражнение':'Выбрать из каталога','secondary small',`data-index="${i}"`)}${c?button('editor-custom','Сделать своим','ghost small',`data-index="${i}"`):''}</div>${c?`<div class="editor-technique">${techniqueButton(e)}<span class="caption">${esc(c.author||'PureGym')} · техника этого упражнения</span></div>`:'<p class="caption mt12">Видео и группы мышц не назначаются автоматически. Можно записывать подходы вручную или выбрать упражнение из каталога.</p>'}<p class="editor-section-label">Твоя нагрузка</p><div class="grid3">${field('e-sets-'+i,'Подходы',e.sets,'number','required min="1" max="20"')}${field('e-reps-'+i,'Начальные повторы',e.reps,'number','required min="0" max="10000"')}${field('e-weight-'+i,c?.equipment.includes('Гантел')?'Гантель, кг':'Вес, кг',e.weight,'number','required min="0" max="1000" step="0.25"')}</div><div class="grid2">${field('e-repMin-'+i,'Повторы от',e.repMin??'','number','min="1" max="1000"')}${field('e-repMax-'+i,'Повторы до',e.repMax??'','number','min="1" max="1000"')}</div><p class="caption">Диапазон цели. Пустые поля — обычная цель по повторам.</p><div class="grid2">${field('e-rest-'+i,'Отдых, сек',e.rest,'number','required min="0" max="1800"')}${field('e-loadStep-'+i,'Шаг веса, кг',e.loadStep||0,'number','required min="0" max="20" step="0.25"')}</div><p class="caption">Шаг — минимальная прибавка на этом снаряде. 0 — ещё не указан.</p><details class="mt12"><summary>Заметка к нагрузке</summary>${field('e-note-'+i,'Текст заметки',e.note||'','text','maxlength="500"')}</details></article>`;}
function renderEditor(){const s=editSession;openModal(s.name?'Изменить тренировку':'Новая тренировка',`<form id="session-form"><details class="session-edit-settings" ${!s.name?'open':''}><summary>Настройки занятия · ${s.duration} мин</summary>${field('session-name','Название',s.name,'text','required maxlength="120"')}<div class="grid2"><div class="field"><label for="session-type">Вид</label><select id="session-type" name="type">${Object.entries(types).filter(([k])=>['gym','swim','home','run'].includes(k)).map(([k,v])=>`<option value="${k}" ${s.type===k?'selected':''}>${v}</option>`).join('')}</select></div>${field('session-duration','Длительность, мин',s.duration,'number','required min="1" max="480"')}</div><div class="field"><label for="session-day">Когда</label><select id="session-day"><option value="">В любой день</option>${days.map((d,i)=>`<option value="${i}" ${s.day===i?'selected':''}>${d}</option>`).join('')}</select></div><div class="field"><label for="session-note">Заметка / интервалы плавания</label><textarea id="session-note" maxlength="2000">${esc(s.note)}</textarea></div></details><div class="section-head"><h3>Упражнения</h3></div><p class="caption">${s.type==='swim'||s.type==='run'?'Записывай время и дистанцию; список упражнений можно оставить пустым.':'Выбери упражнение, затем настрой свои подходы, повторы и вес. Видео относится к выбранному движению.'}</p>${s.exercises.map(editorExercise).join('')}${button('editor-library','+ Из каталога','secondary full')}${button('add-exercise','Написать своё упражнение','ghost full')}<button type="submit" class="primary full spaced">Сохранить тренировку</button>${data.plan.sessions.some(x=>x.id===s.id)?button('remove-session','Убрать из программы','ghost danger full'):''}</form>`);}
function collectEditor(){const s=editSession;s.name=$('#session-name').value;s.type=$('#session-type').value;s.duration=Number($('#session-duration').value);s.day=$('#session-day').value===''?null:Number($('#session-day').value);s.note=$('#session-note').value;for(let i=0;i<s.exercises.length;i++)for(const k of ['name','sets','reps','weight','loadStep','rest','note'])s.exercises[i][k]=['sets','reps','weight','loadStep','rest'].includes(k)?Number($('#e-'+k+'-'+i).value):$('#e-'+k+'-'+i).value;for(let i=0;i<s.exercises.length;i++){const e=s.exercises[i],min=$('#e-repMin-'+i).value,max=$('#e-repMax-'+i).value;if(min===''&&max===''){delete e.repMin;delete e.repMax;}else{e.repMin=Number(min);e.repMax=Number(max);}}}
async function savePlan(plan){const r=await api('plan',{plan,revision:data.revision});data.plan=r.plan;data.revision=r.revision;modal.close();render();toast('Программа сохранена');}
function importPlan(){openModal('Загрузить программу',`<p class="muted">Выбери JSON-файл программы от ChatGPT. История тренировок сохранится.</p><div class="field"><label for="plan-file">Файл программы</label><input type="file" id="plan-file" accept=".json,application/json"></div><p class="caption">После выбора покажем состав программы до сохранения.</p><div id="import-preview"></div>`);}
let pendingPlan=null;


const actions={
 'close':()=>closeModal(),'program-wizard':()=>programWizard(),'wizard-preview':previewProgram,'wizard-save':async()=>{await savePlan(wizardPlan);tab='training';render();},'wizard-edit':()=>programWizard(wizardAnswers),'calendar-day':el=>{selectCalendarDay(el.dataset.day);},'calendar-open':()=>{calendarMonth=new Date(selectedDay+'T12:00:00');calendarMonth.setDate(1);openCalendar();},'month-prev':()=>{calendarMonth.setMonth(calendarMonth.getMonth()-1);openCalendar();},'month-next':()=>{calendarMonth.setMonth(calendarMonth.getMonth()+1);openCalendar();},'month-day':el=>{closeModal();selectCalendarDay(el.dataset.day);},'month-today':()=>{closeModal();selectCalendarDay(dateDay());},'calendar-prev':()=>shiftWeek(-1),'calendar-next':()=>shiftWeek(1),'calendar-today':()=>{selectCalendarDay(dateDay());},'workout-details':el=>workoutDetails(el.dataset.id),'auth-switch':()=>{authMode=authMode==='login'?'register':'login';renderAuth();},'auth-recover':()=>{authMode='recover';renderAuth();},
 'tab':el=>{tab=el.dataset.tab;if(tab==='stats')statsView='overview';render();window.scrollTo(0,0);},'profile':()=>{tab='profile';render();window.scrollTo(0,0);},'home':()=>{tab='today';render();window.scrollTo(0,0);},'stats':()=>{tab='stats';statsView='overview';render();window.scrollTo(0,0);},'training':()=>{tab='training';render();},'period':el=>{period=Number(el.dataset.period);render();},'export':exportData,'import':importPlan,
 'new-session':()=>editor(),'edit-session':el=>editor(data.plan.sessions.find(s=>s.id===el.dataset.id)),'add-exercise':()=>{collectEditor();editSession.exercises.push({exerciseId:null,name:'',sets:3,reps:10,weight:0,rest:90,note:''});renderEditor();},'remove-exercise':el=>{collectEditor();editSession.exercises.splice(Number(el.dataset.index),1);renderEditor();},
 'remove-session':()=>openModal('Убрать тренировку?',`<p class="muted">Она исчезнет из программы. Завершённые занятия останутся в истории.</p>${button('confirm-remove-session','Убрать из программы','primary full spaced')}`),'confirm-remove-session':()=>savePlan({...data.plan,sessions:data.plan.sessions.filter(s=>s.id!==editSession.id)}),
 'confirm-import':()=>savePlan(pendingPlan),
 'start':el=>{if(active){if(modal.open)modal.close();tab='workout';render();return;}preparingId=el.dataset.id;if(!data.plan.sessions.some(s=>s.id===preparingId))throw Error('Занятие не найдено');if(modal.open)modal.close();tab='prepare';render();window.scrollTo(0,0);},'prepare-back':()=>{preparingId=null;tab='training';render();window.scrollTo(0,0);},'begin-workout':async el=>{if(modal.open)modal.close();if(active){tab='workout';render();toast('Сначала заверши текущее занятие');return;}const s=data.plan.sessions.find(s=>s.id===preparingId);if(!s)throw Error('Сначала выбери тренировку');preparingId=null;active={id:crypto.randomUUID(),name:s.name,sessionId:s.id,type:s.type,startedAt:new Date().toISOString(),completedAt:null,note:s.note||'',distance:0,elapsed:0,exercises:s.exercises.map(e=>({name:e.name,exerciseId:findExercise(e)?.id??null,repTarget:e.reps,...(e.repMin!=null?{repMin:e.repMin,repMax:e.repMax}:{}),plannedSets:e.sets,loadStep:e.loadStep||0,rest:e.rest,note:e.note,sets:Array.from({length:e.sets},()=>({weight:e.weight,reps:e.reps,done:false}))}))};await saveWorkout();tab='workout';render();window.scrollTo(0,0);},
 'resume':()=>{tab='workout';render();},'minimize':async()=>{clearTimeout(saveTimer);await saveWorkout();tab='today';render();},'set-done':el=>{const e=active.exercises[Number(el.dataset.ex)],s=e.sets[Number(el.dataset.set)];s.done=!s.done;queueSave();render();},'add-set':el=>{const e=active.exercises[Number(el.dataset.ex)];if(e.sets.length>=30)throw Error('Максимум 30 подходов');e.sets.push({...e.sets.at(-1),done:false});queueSave();render();},'skip-rest':()=>{restUntil=0;tick();},
 'finish':()=>{openModal('Как прошло?',`<p class="muted mb16">Оценка сохранится в истории и поможет выбрать нагрузку в следующий раз.</p><div class="feedback">${[['easy','Легко'],['good','В самый раз'],['hard','Тяжело']].map(([f,l])=>button('feedback',l,'',`data-feedback="${f}"`)).join('')}</div>`);},
 'feedback':async el=>{clearTimeout(saveTimer);await saveChain.catch(()=>{});active.feedback=el.dataset.feedback;active.completedAt=new Date().toISOString();try{await saveWorkout();}catch(e){active.completedAt=null;throw e;}active=null;restUntil=0;modal.close();tab='stats';statsView='overview';await refresh();toast('Тренировка сохранена. Ещё один шаг вперёд.');},
 'discard':()=>openModal('Отменить занятие?',`<p class="muted">Незавершённая тренировка будет удалена.</p>${button('confirm-discard','Отменить занятие','primary full spaced')}`),'confirm-discard':async()=>{clearTimeout(saveTimer);await saveChain.catch(()=>{});await api('workout/discard',{id:active.id});localStorage.removeItem('fitassist-draft-'+data.user.id);active=null;restUntil=0;modal.close();tab='training';await refresh();},
 'logout':async()=>{clearTimeout(saveTimer);if(active)await saveWorkout();await vault.drain();await api('logout',{});active=null;data=null;lastRenderedTab=null;modal.close();renderAuth();},
 'refresh-data':()=>refreshPage(),'retry':()=>refresh()
};
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;const fn=actions[el.dataset.action];if(!fn)return;try{el.disabled=true;await fn(el);}catch(err){showError(err.message);}finally{el.disabled=false;}});
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target,submit=form.querySelector('[type=submit]');if(submit)submit.disabled=true;try{
 if(form.id==='finish-form'){if(surveyWorkoutId)await saveCompletedSurvey();else await completeWorkout(false);}
 if(form.id==='progress-step-form'){await saveProgressStep();}
 if(form.id==='wizard-form'){previewProgram();}
 if(form.id==='auth-form'){const b=Object.fromEntries(new FormData(form));b.mode=authMode;const r=await api('auth',b);await refresh();if(r.recovery)openModal('Сохрани код восстановления',`<p class="muted">Он позволит установить новый пароль, если забудешь старый. Мы не отправляем письма для восстановления.</p><pre class="code token spaced">${esc(r.recovery)}</pre><p class="info spaced">Сохрани код в менеджере паролей. Без пароля и этого кода восстановить аккаунт не получится.</p>${button('close','Я сохранил код','primary full spaced')}`);}
 if(form.id==='profile-form'){const p=Object.fromEntries(new FormData(form));const r=await api('profile',{...data.profile,...p,weeklyGoal:Number(p.weeklyGoal)});data.profile=r.profile;render();toast('Профиль сохранён');}
 if(form.id==='draft-form'){collectDraft();await savePlan(planDraft);}
 if(form.id==='session-form'){collectEditor();const sessions=[...data.plan.sessions],i=sessions.findIndex(s=>s.id===editSession.id);if(i<0)sessions.push(editSession);else sessions[i]=editSession;await savePlan({...data.plan,sessions});}
 }catch(err){if(form.id==='auth-form')$('#auth-error').innerHTML=`<div class="error">${esc(err.message)}</div>`;else showError(err.message);}finally{if(submit)submit.disabled=false;}});
document.addEventListener('change',async e=>{const el=e.target;try{if(el.id==='plan-file'){const file=el.files[0];if(!file)return;if(file.size>150000)throw Error('Файл слишком большой');const p=JSON.parse(await file.text());pendingPlan=p.plan||p;if(typeof pendingPlan.title!=='string'||!Array.isArray(pendingPlan.sessions)||pendingPlan.sessions.length>40)throw Error('В файле нет корректной программы');$('#import-preview').innerHTML=`<div class="info"><h3>${esc(pendingPlan.title)}</h3><p class="caption mt8">${pendingPlan.sessions.length} занятий</p><ul>${pendingPlan.sessions.map(s=>`<li>${esc(s.name)} · ${esc(types[s.type]||s.type)} · ${esc(s.duration)} мин</li>`).join('')}</ul></div>${button('confirm-import','Заменить программу','primary full spaced')}`;}if(el.id==='workout-distance'&&active){active.distance=Number(el.value);queueSave();}if(el.dataset.ex!==undefined&&el.dataset.key&&active){const n=Number(el.value);if(!Number.isFinite(n)||n<0)throw Error('Нужно неотрицательное число');active.exercises[Number(el.dataset.ex)].sets[Number(el.dataset.set)][el.dataset.key]=n;queueSave();}}catch(err){showError(err.message);}});
modal.addEventListener('click',e=>{if(e.target===modal)closeModal();});
window.addEventListener('online',()=>{if(data)refresh().catch(e=>toast(e.message));});window.addEventListener('offline',()=>{if(data)render();});
async function boot(){if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});try{await refresh();const draft=localStorage.getItem('fitassist-draft-'+data.user.id);if(draft){const w=JSON.parse(draft);const completedSame=data.workouts.some(x=>x.id===w.id&&x.completedAt);if(!completedSame){active=w;tab='workout';toast('Восстановлена несохранённая тренировка');render();}else localStorage.removeItem('fitassist-draft-'+data.user.id);}}catch(e){if(data===null)renderAuth();else root.innerHTML=`<main class="auth"><h1>Не удалось загрузить данные</h1><p class="muted spaced">${esc(e.message)}</p>${button('retry','Попробовать снова','primary spaced')}</main>`;}}
boot();

// iOS uses the readable input size instead of focus zoom. Never disable pinch zoom.
let clearViewportHeight=window.visualViewport?.height||innerHeight;
function syncKeyboard(){const vv=window.visualViewport,focused=document.activeElement?.matches('input,textarea,select');if(!vv)return;if(!focused)clearViewportHeight=Math.max(clearViewportHeight,vv.height);const keyboard=focused&&vv.scale<=1.05&&(innerHeight-vv.height>130||clearViewportHeight-vv.height>130);document.documentElement.classList.toggle('keyboard-open',Boolean(keyboard));document.documentElement.style.setProperty('--visual-height',Math.round(vv.height-24)+'px');}
window.visualViewport?.addEventListener('resize',syncKeyboard);document.addEventListener('focusin',syncKeyboard);document.addEventListener('focusout',()=>requestAnimationFrame(syncKeyboard));

function openCalendar(){
 const start=new Date(calendarMonth),offset=(start.getDay()+6)%7;start.setDate(1-offset);
 const cells=Array.from({length:42},(_,i)=>{const d=new Date(start);d.setDate(start.getDate()+i);const key=dateDay(d),records=completed().filter(w=>dateDay(new Date(w.startedAt||w.completedAt))===key),kinds=[...new Set(records.map(w=>w.type))];return '<button class="month-day '+(d.getMonth()!==calendarMonth.getMonth()?'outside ':'')+(key===selectedDay?'selected ':'')+(key===dateDay()?'current':'')+'" data-action="month-day" data-day="'+key+'" aria-label="'+fullCalendarDate(key)+(records.length?', выполнено занятий: '+records.length:'')+'" aria-pressed="'+(key===selectedDay)+'"><span>'+d.getDate()+'</span><span class="day-marks">'+kinds.map(t=>'<i class="activity-dot dot-'+t+'"></i>').join('')+'</span></button>';}).join('');
 openModal('Календарь', '<div class="month-toolbar">'+button('month-prev',icon('chevron'),'icon-button calendar-prev','aria-label="Предыдущий месяц"')+'<h3>'+calendarMonth.toLocaleDateString('ru-RU',{month:'long',year:'numeric'})+'</h3>'+button('month-next',icon('chevron'),'icon-button','aria-label="Следующий месяц"')+'</div><div class="month-weekdays">'+['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].map(d=>'<span>'+d+'</span>').join('')+'</div><div class="month-grid">'+cells+'</div><div class="calendar-legend mt12"><span><i class="activity-dot dot-gym"></i>Зал</span><span><i class="activity-dot dot-swim"></i>Бассейн</span>'+cardioLegend()+'</div>'+button('month-today','К сегодняшнему дню','secondary full spaced'));
}
function selectCalendarDay(day){
 if(selectedDay===day)return;
 const oldWeek=document.querySelector('.week'),oldMarker=document.querySelector('.week-selection'),oldBounds=oldMarker?.getBoundingClientRect(),oldWeekBounds=oldWeek?.getBoundingClientRect(),oldWeekKey=oldWeek?.dataset.week;
 const date=new Date(day+'T12:00:00'),monday=new Date(date);monday.setDate(date.getDate()-(date.getDay()+6)%7);const nextWeekKey=dateDay(monday),sameWeek=oldWeekKey===nextWeekKey;
 selectedDay=day;
 if(sameWeek&&oldMarker){
  oldMarker.getAnimations().forEach(a=>a.cancel());
  document.querySelectorAll('.week .day').forEach(button=>{const chosen=button.dataset.day===day;button.classList.toggle('is-selected',chosen);button.setAttribute('aria-pressed',String(chosen));});
  oldMarker.dataset.index=String((date.getDay()+6)%7);
  const month=document.querySelector('.calendar-home-header .calendar-month-button span'),year=document.querySelector('.calendar-home-header .calendar-month-button small');if(month)month.textContent=date.toLocaleDateString('ru-RU',{month:'long'});if(year)year.textContent=date.getFullYear();
  const live=document.querySelector('.selected-date');if(live)live.textContent=fullCalendarDate(day);
  const today=document.querySelector('[data-action="calendar-today"]');if(today)today.disabled=day===dateDay();
 }else render();
 if(!motionAllowed())return;
 const week=document.querySelector('.week'),marker=document.querySelector('.week-selection');
 if(sameWeek&&oldBounds&&oldWeekBounds&&marker){const next=marker.getBoundingClientRect(),relative=oldBounds.left-oldWeekBounds.left-(next.left-week.getBoundingClientRect().left);marker.animate([{transform:'translateX('+relative+'px)'},{transform:'translateX(0)'}],{duration:380,easing:'cubic-bezier(.22,.8,.25,1)'});}
 else if(week){const direction=oldWeekKey&&week.dataset.week<oldWeekKey?-1:1;week.animate([{opacity:0,transform:'translateX('+direction*32+'px)'},{opacity:1,transform:'translateX(0)'}],{duration:360,easing:'cubic-bezier(.16,1,.3,1)'});document.querySelector('.calendar-month-button')?.animate([{opacity:.4},{opacity:1}],{duration:260,easing:'ease-out'});}
}

let calendarTouch=null;
document.addEventListener('touchstart',event=>{const panel=event.target.closest('.calendar-panel');calendarTouch=panel&&event.touches.length===1?{x:event.touches[0].clientX,y:event.touches[0].clientY}:null;},{passive:true});
document.addEventListener('touchend',event=>{if(!calendarTouch||!event.changedTouches.length)return;const dx=event.changedTouches[0].clientX-calendarTouch.x,dy=event.changedTouches[0].clientY-calendarTouch.y;calendarTouch=null;if(Math.abs(dx)>55&&Math.abs(dx)>Math.abs(dy)*1.5)shiftWeek(dx<0?1:-1);},{passive:true});
document.addEventListener('touchcancel',()=>{calendarTouch=null;},{passive:true});
function shiftWeek(direction){const d=new Date(selectedDay+'T12:00:00');d.setDate(d.getDate()+direction*7);selectCalendarDay(dateDay(d));}
let wizardAnswers=null,wizardPlan=null;
function programWizard(){openModal('Выбери свой вариант',`<p class="muted">Два дня зала + один бассейн. Силовые без упражнений на ноги. Каждый вариант можно изменить под себя.</p><div class="variant-list spaced">${variants.map(v=>`<button class="variant-option" data-action="variant-preview" data-variant="${v.id}"><span class="eyebrow">${v.label}</span><strong>${v.name}</strong><span class="caption">${v.description}</span><span class="variant-arrow">${icon('arrow')}</span></button>`).join('')}</div><div class="stack spaced">${button('custom-program','Взять мою программу за основу','secondary full')}${button('new-custom-program','Собрать свою с нуля','ghost full')}</div>`);}
function previewProgram(){programWizard();}
function workoutDetails(id){const w=data.workouts.find(w=>w.id===id);if(!w)return;openModal(w.name,`<p class="caption">${humanDate(w.completedAt||w.startedAt)} · ${types[w.type]}</p><div class="weight-summary"><div><p class="caption">Время</p><p class="number">${time(w.elapsed)}</p></div><div><p class="caption">${w.distance?'Дистанция':'Подходы'}</p><p class="number">${w.distance?fmt(w.distance):w.exercises.reduce((n,e)=>n+e.sets.filter(s=>s.done).length,0)} <span class="unit">${w.distance?'м':''}</span></p></div></div>${w.feedback?'<p class="info">Оценка занятия: '+{easy:'легко',good:'в самый раз',hard:'тяжело'}[w.feedback]+'</p>':''}${wellbeingSummary(w)}${button('review-workout',w.survey?'Опрос: посмотреть или изменить':'Пройти опрос после тренировки','secondary full spaced',`data-id="${esc(w.id)}"`)}${w.exercises.map(e=>'<section class="exercise"><h3>'+esc(e.name)+'</h3>'+e.sets.map((s,i)=>'<div class="row between mt12 caption"><span>Подход '+(i+1)+'</span><strong>'+s.weight+' кг × '+s.reps+'</strong><span>'+(s.done?'Выполнен':'Пропущен')+'</span></div>').join('')+'</section>').join('')}${w.note?'<p class="caption plan-note spaced">'+esc(w.note)+'</p>':''}`);}


function showError(message){if(!modal.open){toast(message);return;}let alert=document.querySelector("#modal-content > .error");if(!alert){alert=document.createElement("p");alert.className="error";alert.setAttribute("role","alert");document.querySelector("#modal-content .modal-head").after(alert);}alert.textContent=message;alert.scrollIntoView({block:"nearest"});}
function motionAllowed(){return !matchMedia('(prefers-reduced-motion: reduce)').matches;}
function animateSheet(){if(!motionAllowed())return;const el=$('#modal-content');el.getAnimations().forEach(a=>a.cancel());el.animate([{opacity:0,transform:'translateY(18px)'},{opacity:1,transform:'translateY(0)'}],{duration:300,easing:'cubic-bezier(.2,.8,.2,1)'});modal.scrollTop=0;}
function animatePage(){if(!motionAllowed())return;document.querySelectorAll('.content .card,.content .week,.content .tabs').forEach((el,i)=>{if(i<9)el.animate([{opacity:0,transform:'translateY(18px)'},{opacity:1,transform:'translateY(0)'}],{duration:380,delay:Math.min(i*38,190),easing:'cubic-bezier(.2,.8,.2,1)',fill:'backwards'});});}
async function closeModal(){if(!modal.open)return;if(motionAllowed()){const a=$('#modal-content').animate([{opacity:1,transform:'translateY(0)'},{opacity:0,transform:'translateY(16px)'}],{duration:150,easing:'ease-in'});try{await a.finished;}catch{}}modal.close();}
modal.addEventListener('cancel',e=>{e.preventDefault();closeModal();});
document.addEventListener('pointerdown',e=>{const el=e.target.closest('button,.choice span');if(!el||!motionAllowed()||el.disabled)return;el.animate([{transform:'scale(1)'},{transform:'scale(.95)'},{transform:'scale(1)'}],{duration:260,easing:'cubic-bezier(.2,.8,.2,1)'});});

let planDraft=null,libraryContext=null,videoBackHTML=null;
function adviceView(plan){return '<div class="plan-advice">'+assessPlan(plan).map(a=>'<p class="advice-item '+a.tone+'">'+icon(a.tone==='good'?'check':'chat')+'<span>'+esc(a.text)+'</span></p>').join('')+'</div>';}
function gearChecklist(type,day=selectedDay){const items=gear[type];if(!items)return '';let checked=[];const key='fitassist-gear-'+data.user.id+'-'+day+'-'+type;try{checked=JSON.parse(localStorage.getItem(key)||'[]');}catch{}return '<details class="card gear-card spaced"><summary>'+icon(type==='swim'?'swim':'gym')+'<span>Что взять с собой<span class="caption gear-caption">'+checked.length+' / '+items.length+' собрано</span></span>'+icon('chevron')+'</summary><div class="gear-list">'+items.map(([id,name])=>'<label><input type="checkbox" data-gear="'+id+'" data-gear-key="'+esc(key)+'" '+(checked.includes(id)?'checked':'')+'><span>'+esc(name)+'</span></label>').join('')+'</div>'+(type==='swim'?'<p class="caption mt12">По твоему списку правил: перед водой — душ без купальника. Шапочка обязательна; очки — по желанию.</p>':'<p class="caption mt12">Закрытая сменная обувь и спортивная форма. Полотенце — на скамью, вода — под рукой.</p>')+'</details>';}
function techniqueButton(name){const e=findExercise(name);return e?button('technique',icon('play')+' Техника'+(e.seconds?' · '+videoTime(e.seconds):''),'technique-link','data-exercise="'+e.id+'"'):'';}
function videoTime(seconds){return seconds<60?seconds+' сек':Math.floor(seconds/60)+':'+String(seconds%60).padStart(2,'0');}
function showTechnique(id){
 const e=[...exercises,...swimVideos].find(e=>e.id===id);if(!e)return;
 const logged=active?.exercises.find(x=>findExercise(x)?.id===id),planned=data.plan.sessions.flatMap(s=>s.exercises).find(x=>findExercise(x)?.id===id),note=logged?.note||planned?.note;
 openModal(e.name,button('technique-back','← Вернуться','ghost small')+(videoEmbedUrl(e)&&navigator.onLine?'<div class="technique-video"><iframe src="'+esc(videoEmbedUrl(e))+'" title="'+esc(e.name)+' — техника" allow="encrypted-media; picture-in-picture; fullscreen" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe></div>':'<div class="info spaced">Текстовая техника доступна на телефоне. Дополнительные материалы — по ссылке источника.</div>')+'<p class="technique-credit">'+esc(e.author||'PureGym')+(e.seconds?' · '+videoTime(e.seconds):' · техника упражнения')+'</p>'+muscleBadge(e)+(e.equipment?'<p class="equipment-label mt12">'+esc(e.equipment)+'</p>':'')+exerciseGuide(e,{open:true})+'<p class="caption mt12">'+esc(e.cue)+'</p>'+(note?'<section class="technique-notes spaced"><h3>Нагрузка и заметки</h3><p class="caption plan-note mt12">'+esc(note)+'</p></section>':'')+'<div class="video-links spaced">'+(e.video?'<a class="secondary" href="'+esc(videoWatchUrl(e))+'" target="_blank" rel="noopener noreferrer">Открыть видео</a>':'')+'<a class="ghost small" href="'+esc(e.source)+'" target="_blank" rel="noopener noreferrer">Источник</a></div>');
}

function swimTechniqueLinks(){return '<div class="swim-techniques">'+swimVideos.map(e=>button('technique',icon('play')+' '+e.name+' · '+videoTime(e.seconds),'secondary full','data-exercise="'+e.id+'"')).join('')+'</div>';}
function sessionDetails(id){if(!data.plan.sessions.some(s=>s.id===id))return;if(tab!=='session')sessionReturn={tab,scroll:window.scrollY};selectedSessionId=id;if(modal.open)modal.close();tab='session';render();window.scrollTo(0,0);}
function renderSessionDetails(){
 const id=selectedSessionId;
 const s=data.plan.sessions.find(s=>s.id===id);if(!s)return header('Занятие не найдено','')+button('session-back','К программе','secondary');
 return `<section class="session-screen"><div class="page-header">${button('session-back',icon('chevron')+'Назад','ghost detail-back')}${header(s.name,'')}</div><div class="row between"><span class="tag">${sessionLabel(s)}</span><span class="caption">${s.duration} мин · ${types[s.type]}</span></div>${gearChecklist(s.type,upcomingSessions([s],selectedDay)[0]?.day||selectedDay)}${sessionAdviceView(s)}${s.note?`<details class="session-guidance spaced" ${s.type==='swim'?'open':''}><summary>Как проходит занятие</summary>${lessonView(s.note,s.type)}</details>`:''}${s.type==='swim'?swimTechniqueLinks():''}<div class="session-exercises spaced">${s.exercises.map((e,i)=>`<article class="exercise-summary"><div class="row between"><span class="exercise-order">${i+1}</span><h3>${esc(e.name)}</h3></div><p class="caption mt8">${e.sets} подх. · ${repLabel(e)} повторов · отдых ${e.rest} сек</p>${exerciseBrief(e)}${muscleBadge(e)}${previousExerciseView(e)}${archiveView(data.profile?.trainingArchive,e)}${progressionCard(s,e,i)}<div class="exercise-actions mt12">${techniqueButton(e)}${button('replace-planned','Заменить','ghost small',`data-session="${esc(s.id)}" data-index="${i}"`)}</div></article>`).join('')}</div>${cardioFinisher(s)}<div class="stack spaced">${button('start','Начать тренировку','primary full',`data-id="${esc(s.id)}"`)}${button('edit-session','Изменить занятие','secondary full',`data-id="${esc(s.id)}"`)}</div></section>`;
}
function previewVariant(id){wizardPlan=makeThreeDayPlan(id);openModal(wizardPlan.title,'<p class="muted">День 1 — зал, день 2 — бассейн, день 3 — зал. Даты выбираешь сам; между силовыми занятиями оставляй день отдыха.</p><p class="info spaced">Первые две недели — по 2 рабочих подхода, лёгкая нагрузка и запас повторов. Для зала 8–12 повторов; в воде отрезки по 25 м с отдыхом.</p><div class="variant-preview spaced">'+wizardPlan.sessions.map((s,i)=>'<article class="card quiet"><span class="tag">'+('День '+(i+1))+' · '+s.duration+' мин</span><h3 class="mt12">'+esc(s.name)+'</h3><p class="caption mt8">'+(s.exercises.length?s.exercises.map(e=>esc(e.name)).join(' · '):'150–200 м как необязательный ориентир, с паузами. Первый раз в воде 20–30 минут.')+'</p></article>').join('')+'</div>'+adviceView(wizardPlan)+'<p class="caption spaced">Сохранение заменит текущую программу. История останется.</p><div class="stack spaced">'+button('wizard-save','Выбрать этот вариант','primary full')+button('custom-from-preview','Изменить под себя','secondary full')+button('program-wizard','Назад к вариантам','ghost full')+'</div>');}
function customProgram(mode='current'){libraryContext=null;planDraft=mode==='new'?{title:'Моя программа',sessions:[]}:structuredClone(mode==='preview'?wizardPlan:data.plan);renderDraft();}
function collectDraft(){const form=$('#draft-form');if(!form||!planDraft)return;planDraft.title=$('#draft-title').value;planDraft.sessions.forEach((s,i)=>{s.name=$('#draft-name-'+i).value;s.day=$('#draft-day-'+i).value===''?null:Number($('#draft-day-'+i).value);s.duration=Number($('#draft-duration-'+i).value);s.note=$('#draft-note-'+i).value;s.exercises.forEach((e,j)=>{const name=$('#draft-ex-name-'+i+'-'+j);if(name)e.name=name.value;for(const key of ['sets','reps','weight'])e[key]=Number($('#draft-'+key+'-'+i+'-'+j).value);const min=$('#draft-repMin-'+i+'-'+j).value,max=$('#draft-repMax-'+i+'-'+j).value;if(min===''&&max===''){delete e.repMin;delete e.repMax;}else{e.repMin=Number(min);e.repMax=Number(max);}});});}
function renderDraft(){const p=planDraft,open=libraryContext?.mode==='draft'?libraryContext.session:0;openModal('Своя программа','<p class="muted">Изменения сохранятся только после нажатия «Сохранить программу».</p><form id="draft-form">'+field('draft-title','Название программы',p.title,'text','required maxlength="120"')+p.sessions.map((s,i)=>'<details class="draft-session" '+(i===open?'open':'')+'><summary>'+esc(s.name)+' · '+(s.day==null?'Без дня':days[s.day])+'</summary><div class="row between"><span class="tag">'+types[s.type]+'</span>'+button('draft-remove-session','Удалить занятие','ghost small danger','data-session-index="'+i+'"')+'</div>'+field('draft-name-'+i,'Название занятия',s.name,'text','required maxlength="120"')+'<div class="grid2"><div class="field"><label for="draft-day-'+i+'">День</label><select id="draft-day-'+i+'"><option value="">Без дня</option>'+days.map((d,k)=>'<option value="'+k+'" '+(s.day===k?'selected':'')+'>'+d+'</option>').join('')+'</select></div>'+field('draft-duration-'+i,'Минут',s.duration,'number','required min="1" max="480"')+'</div><div class="field"><label for="draft-note-'+i+'">Как выполнять</label><textarea id="draft-note-'+i+'" maxlength="2000">'+esc(s.note)+'</textarea></div>'+s.exercises.map((e,j)=>'<div class="draft-exercise"><div class="row between"><strong>'+esc(e.name)+'</strong>'+button('draft-remove-exercise',icon('close'),'icon-button','data-session-index="'+i+'" data-index="'+j+'" aria-label="Убрать '+esc(e.name)+'"')+'</div><p class="caption mt8">'+(findExercise(e)?'Из каталога · '+esc(findExercise(e).equipment):'Своё упражнение · без привязанного видео')+'</p>'+(!findExercise(e)?field('draft-ex-name-'+i+'-'+j,'Название',e.name,'text','required maxlength="160"'):'')+'<div class="grid3">'+field('draft-sets-'+i+'-'+j,'Подходы',e.sets,'number','required min="1" max="20"')+field('draft-reps-'+i+'-'+j,'Повторы (цель '+repLabel(e)+')',e.reps,'number','required min="0" max="10000"')+field('draft-weight-'+i+'-'+j,'Вес, кг',e.weight,'number','required min="0" max="1000" step="0.25"')+'</div><div class="grid2">'+field('draft-repMin-'+i+'-'+j,'Повторы от',e.repMin??'','number','min="1" max="1000"')+field('draft-repMax-'+i+'-'+j,'Повторы до',e.repMax??'','number','min="1" max="1000"')+'</div><div class="exercise-actions">'+techniqueButton(e)+button('draft-replace','Предложить замену','ghost small','data-session-index="'+i+'" data-index="'+j+'"')+'</div></div>').join('')+(s.type==='swim'?'<p class="caption">Для бассейна записывай интервалы в инструкции и фактическую дистанцию в занятии.</p>':button('draft-add-exercise','+ Из каталога упражнений','secondary full','data-session-index="'+i+'"')+button('draft-add-custom','+ Своё упражнение','ghost full','data-session-index="'+i+'"'))+'</details>').join('')+'<div class="program-tools spaced">'+button('draft-add-session','+ Зал','secondary','data-type="gym"')+button('draft-add-session','+ Бассейн','secondary','data-type="swim"')+'</div><div class="section-head"><h3>Советы по программе</h3>'+button('draft-review','Обновить проверку','ghost small')+'</div><div id="draft-advice">'+adviceView(p)+'</div><div class="draft-save-bar"><button type="submit" class="primary full">Сохранить программу</button></div></form>');}
function openLibrary(context){libraryContext=context;const current=context.exercise?findExercise(context.exercise):context.name?findExercise(context.name):null,list=current?replacements(current.name):exercises;const title=current?'Замена: '+current.name:'Каталог упражнений';openModal(title,'<p class="muted">'+(current?'Похожие движения для той же задачи. При замене подбери вес заново.':'Нажми упражнение, чтобы добавить. Короткая техника — по кнопке видео.')+'</p><div class="library-list spaced">'+(list.length?list.map(e=>'<article class="library-option"><div class="row between"><div><h3>'+esc(e.name)+'</h3><p class="caption mt8">'+esc(e.equipment)+'</p></div>'+button('technique',icon('play'),'icon-button','data-exercise="'+e.id+'" aria-label="Видео: '+esc(e.name)+'"')+'</div><p class="caption mt12">'+esc(e.cue)+'</p>'+button('library-pick',current?'Выбрать замену':'Добавить','secondary full mt12','data-exercise="'+e.id+'"')+'</article>').join(''):'<p class="info">В проверенном каталоге пока нет равноценной замены. Можно выбрать другое упражнение в полном каталоге; сравни задачу и оборудование.</p>')+'</div><div class="stack spaced">'+(current?button('library-all','Показать весь каталог','secondary full'):'')+button('library-back','Вернуться к программе','ghost full')+'</div>');}
function pickLibrary(id){const found=exercises.find(e=>e.id===id),c=libraryContext;if(!found||!c)return;const previous=c.mode==='editor'?editSession.exercises[c.index]:planDraft?.sessions[c.session]?.exercises[c.index];const e=catalogExercise(id,previous||{});if(c.mode==='editor'){if(c.index!=null)editSession.exercises[c.index]=e;else editSession.exercises.push(e);renderEditor();return;}const s=planDraft.sessions[c.session];if(c.index!=null){e.sets=s.exercises[c.index].sets;e.reps=s.exercises[c.index].reps;e.rest=s.exercises[c.index].rest;s.exercises[c.index]=e;}else s.exercises.push(e);renderDraft();}
