document.addEventListener('change',e=>{const el=e.target;if(!el.dataset.gear)return;const key=el.dataset.gearKey;const scope=el.closest('.gear-list');const checked=[...scope.querySelectorAll('input:checked')].map(x=>x.dataset.gear);try{localStorage.setItem(key,JSON.stringify(checked));}catch{}el.closest('details').querySelector('.gear-caption').textContent=checked.length+' / '+scope.querySelectorAll('input').length+' собрано';});

