function sessionAdviceView(s){const a=sessionAdvice(data.workouts,s);return a?'<div class="plan-advice"><p class="advice-item '+a.tone+'"><span><strong>По последним занятиям</strong><br>'+esc(a.text)+'</span></p></div>':'';}

function exerciseBrief(e){const c=findExercise(e);return '<p class="equipment-label mt12">'+esc(c?.equipment||'Своё упражнение')+'</p><p class="exercise-cue mt8">'+esc(c?.cue||String(e.note||'Записывай фактические вес и повторения.').split(/(?<=[.!?])\s/)[0])+'</p>';}
function historyIdentity(e){const c=findExercise(e);return 'data-name="'+esc(e.name)+'" data-catalog-id="'+(c?c.id:'')+'" data-own="'+(c?'0':'1')+'"';}
function previousExerciseView(e){
 const r=exerciseHistory(e,data.workouts,{before:active?Date.parse(active.startedAt):Infinity})[0];
 if(!r&&archiveView(data.profile?.trainingArchive,e))return '';
 const groups=new Map();for(const s of r?.sets||[]){const key=s.weight+':'+s.reps;const g=groups.get(key);if(g)g.count++;else groups.set(key,{...s,count:1});}
 return '<button type="button" class="previous-result compact-previous full mt12" data-action="exercise-history" '+historyIdentity(e)+' aria-label="История упражнения '+esc(e.name)+'"><span class="previous-heading"><span>Прошлое занятие</span><span class="previous-date">'+(r?humanDate(r.date):'')+icon('chevron')+'</span></span>'+(r?[...groups.values()].map(s=>'<span class="previous-values"><span><strong>'+(s.weight?fmt(s.weight,2):'—')+'</strong><small>кг</small></span><span><strong>'+fmt(s.reps)+'</strong><small>повт.</small></span><span><strong>'+s.count+'</strong><small>подх.</small></span></span>').join(''):'<span class="caption">Пока нет записей</span>')+'</button>';
}
function exerciseHistoryModal(name,exerciseId){
 const e={name,...(exerciseId!==undefined?{exerciseId}:{})},rows=exerciseHistory(e,data.workouts),insight=plateauInsight(e,data.workouts);
 const points=rows.slice(0,12).reverse(),max=Math.max(1,...points.flatMap(r=>r.sets.map(s=>s.weight)));
 const chart=points.length>1&&max>1?'<div class="exercise-chart" role="img" aria-label="Максимальный записанный вес в каждом из последних '+points.length+' занятий"><svg viewBox="0 0 300 100" aria-hidden="true"><path class="chart-base" d="M8 88H292"/><polyline points="'+points.map((r,i)=>(8+i*284/(points.length-1))+','+(88-Math.max(...r.sets.map(s=>s.weight))/max*72)).join(' ')+'"/>'+points.map((r,i)=>'<circle cx="'+(8+i*284/(points.length-1))+'" cy="'+(88-Math.max(...r.sets.map(s=>s.weight))/max*72)+'" r="3"/>').join('')+'</svg><div class="row between caption"><span>'+humanDate(points[0].date)+'</span><span>'+humanDate(points.at(-1).date)+'</span></div><p class="caption mt8">Максимальный вес за занятие, кг. Точные веса и повторы — ниже. Сравнивай один и тот же снаряд.</p></div>':'';
 openModal(name,chart+'<div class="insight-note spaced"><strong>'+({possible:'Возможно плато',progress:'Есть прогресс',changed:'Условия изменились',insufficient:'Собираем историю'}[insight.status])+'</strong><p class="caption mt8">'+esc(insight.reason)+'</p></div><div class="exercise-timeline spaced">'+(rows.length?rows.map(r=>'<article class="exercise-log"><div class="row between"><strong>'+humanDate(r.date)+'</strong><span class="caption">'+r.sets.length+' подх.</span></div><p class="caption mt8">'+esc(r.session)+'</p><ol class="logged-sets">'+r.sets.map(s=>'<li><span>'+(s.weight?fmt(s.weight,2)+' кг':'Без веса')+'</span><strong>× '+fmt(s.reps)+'</strong></li>').join('')+'</ol></article>').join(''):'<div class="empty"><h3>Пока нет выполненных подходов</h3><p>Запиши вес, повторы и отметь подход. После завершения занятия он появится здесь.</p></div>')+'</div>');
}
function weeklySummaryView(){
 const s=weekSummary(data.workouts,dateDay()),w=s.current,p=s.previous,goal=data.profile.weeklyGoal||3;
 const labels=['Пн','Вт','Ср','Чт','Пт','Сб','Вс'];
 return '<article class="card weekly-summary"><div class="row between"><h2>Эта неделя</h2><span class="tag">'+humanDate(s.start)+' — '+humanDate(new Date(s.end.getTime()-86400000))+'</span></div><div class="week-facts mt12"><div><strong>'+w.count+' / '+goal+'</strong><span>занятий</span></div><div><strong>'+w.minutes+'</strong><span>минут</span></div><div><strong>'+fmt(w.distance)+'</strong><span>метров в воде</span></div></div><div class="week-bars mt12">'+w.days.map((n,i)=>'<div><span class="week-bar" style="height:'+Math.max(4,Math.min(n,4)*10)+'px" aria-hidden="true"></span><span>'+labels[i]+'</span><span class="sr-only">: '+n+' занятий</span></div>').join('')+'</div><p class="caption mt12">Выполнено подходов: '+w.sets+'. '+(w.count>=goal?'План недели выполнен.':w.count?'Продолжай в своём ритме.':'Завершённые занятия появятся здесь.')+'</p><details class="mt12"><summary>Прошлая полная неделя</summary><p class="caption mt8">'+p.count+' занятий · '+p.minutes+' мин · '+p.sets+' подходов · '+fmt(p.distance)+' м в воде.</p><p class="caption mt8">Текущая неделя ещё может продолжаться: проценты роста с полной неделей не сравниваем.</p></details></article>';
}
function plateauOverview(){
 const unique=new Map();for(const w of completed())for(const e of w.exercises)unique.set(exerciseKey(e),e);
 const candidates=[...unique.values()].filter(e=>plateauInsight(e,data.workouts).status==='possible');
 return '<div class="section-head"><h2>Динамика нагрузки</h2></div><div class="card">'+(candidates.length?'<p class="caption">Возможно плато. Программа не меняется автоматически.</p>'+candidates.map(e=>button('exercise-history',esc(e.name)+' '+icon('chevron'),'secondary full mt12',historyIdentity(e))).join(''):'<p>Сигналов плато пока нет</p><p class="caption mt8">Проверяем четыре сопоставимых занятия за 3–6 недель: тот же вес, число подходов и цель повторов. При малом количестве записей выводов не делаем.</p>')+'</div>';
}
